import type { Article, DocBlock, DocumentationPlatform, DocumentationRisk, DocumentationStatus } from "./types";
import { getBookingFeature, type BookingFeature } from "./booking-registry";

/**
 * Booking documentation is intentionally kept as authored content. The registry in
 * /docs/booking is the machine-readable source for discovery and CI; this file is the
 * human-readable source that the Help Center renders.
 */

type LocalizedCopy = {
  title: string;
  description: string;
  blocks: DocBlock[];
};

type BookingArticleSpec = {
  id: string;
  category: string;
  order: number;
  featureId: string;
  platform: DocumentationPlatform;
  status: DocumentationStatus;
  risk: DocumentationRisk;
  tags: string[];
  keywords: string[];
  permissions?: string[];
  screenshotIds?: string[];
  en: LocalizedCopy;
  sq: LocalizedCopy;
};

const h = (id: string, text: string, level: 2 | 3 = 2): DocBlock => ({ type: "heading", id, text, level });
const p = (text: string): DocBlock => ({ type: "paragraph", text });
const list = (items: string[], ordered = false): DocBlock => ({ type: "list", items, ordered });
const note = (text: string, title?: string): DocBlock => ({ type: "callout", tone: "note", text, title });
const tip = (text: string, title?: string): DocBlock => ({ type: "callout", tone: "tip", text, title });
const warning = (text: string, title?: string): DocBlock => ({ type: "callout", tone: "warning", text, title });
const danger = (text: string, title?: string): DocBlock => ({ type: "callout", tone: "danger", text, title });
const steps = (items: Array<{ title: string; text?: string; screenshot?: Extract<DocBlock, { type: "screenshot" }> }>, id?: string): DocBlock => ({ type: "steps", id, items });
const circledNumbers = ["⓪", "①", "②", "③", "④", "⑤", "⑥", "⑦", "⑧", "⑨", "⑩"];
const shot = (screenshotId: string, alt: string, caption: string, annotations: Array<[string, string, string]> = []): DocBlock => ({
  type: "screenshot",
  screenshotId,
  scenario: screenshotId,
  alt,
  caption,
  annotations: annotations.map(([number, label, description]) => ({ number: circledNumbers[Number(number)] ?? number, label, description })),
});

const article = (spec: BookingArticleSpec, locale: "en" | "sq"): Article => {
  const copy = spec[locale];
  type RegistryVerification = Partial<Record<"lastVerifiedCommit" | "lastDocumentationCommit" | "lastScreenshotCommit" | "lastAutomatedVerification" | "latestRelevantApplicationCommit" | "availableSince", string | null>> & Partial<Record<"reviewStatus", "approved" | "review_required" | "outdated" | "missing">>;
  const registryFeature = getBookingFeature(spec.featureId) as (BookingFeature & RegistryVerification) | undefined;
  return {
    id: spec.id,
    translationId: spec.id,
    locale,
    title: copy.title,
    description: copy.description,
    product: "booking",
    category: spec.category,
    slug: spec.id,
    order: spec.order,
    tags: spec.tags,
    keywords: spec.keywords,
    lastUpdated: "2026-08-25",
    readingTime: "6 min",
    draft: false,
    platform: spec.platform,
    featureId: spec.featureId,
    documentationStatus: spec.status,
    riskLevel: spec.risk,
    requiredPermissions: spec.permissions,
    screenshotIds: spec.screenshotIds,
    visualGuide: Boolean(spec.screenshotIds?.length),
    lastVerifiedCommit: registryFeature?.lastVerifiedCommit ?? undefined,
    lastScreenshotCommit: registryFeature?.lastScreenshotCommit ?? undefined,
    latestRelevantApplicationCommit: registryFeature?.latestRelevantApplicationCommit ?? undefined,
    availableSince: registryFeature?.availableSince ?? undefined,
    documentation: {
      lastVerifiedCommit: registryFeature?.lastVerifiedCommit ?? undefined,
      lastDocumentationCommit: registryFeature?.lastDocumentationCommit ?? undefined,
      lastScreenshotCommit: registryFeature?.lastScreenshotCommit ?? undefined,
      lastAutomatedVerification: registryFeature?.lastAutomatedVerification ?? undefined,
      latestRelevantApplicationCommit: registryFeature?.latestRelevantApplicationCommit ?? undefined,
      reviewStatus: registryFeature?.reviewStatus ?? (spec.status === "REVIEW_REQUIRED" ? "review_required" : "approved"),
      screenshotIds: spec.screenshotIds,
    },
    blocks: copy.blocks,
    related: [],
  };
};

